script:
const keyword = ctx.params.tu_khoa || ctx.testPrefix;
const fold = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[đĐ]/g, 'd').toLowerCase();

await step('Nhập từ khóa vào ô tìm kiếm', async () => {
  await page.waitForLoadState('networkidle', { timeout: 20000 }).catch(() => {});
  const box = page.getByPlaceholder('Tìm kiếm theo tiêu đề hoặc tên người gửi...');
  await box.click();
  await box.pressSequentially(keyword);
  await box.press('Enter');
});

await step('Chuyển sang trang kết quả tìm kiếm', async () => {
  await page.waitForURL(/\/internal_mailold\/search\?/, { timeout: 30000 });
  await page.locator('tbody tr .mail-content__subject').first().waitFor({ timeout: 30000 });
});

await step('Có kết quả khớp từ khóa', async () => {
  const total = await page.getByText(/Tổng cộng \d+ kết quả/).first().innerText();
  const n = parseInt((total.match(/\d+/) || ['0'])[0], 10);
  assert(n >= 1, 'Không có kết quả nào cho từ khóa ' + keyword);
  const subjects = await page.locator('tbody tr .mail-content__subject').allInnerTexts();
  assert(subjects.some(s => fold(s).includes(fold(keyword))), 'Không thư nào có tiêu đề chứa ' + keyword);
  ctx.log(total.trim());
});
